// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { DemoStage, MockPage, PanelChrome, type Build } from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { CAPTIONS, DEVICES, STATES, URLS } from './script'

const SCALE = 0.2
const LABEL = 14
const GAP = 6
const height = (id: string) =>
  Math.round((DEVICES.find((device) => device.id === id)?.frame ?? 0) * SCALE)

function layout(selected: string[]) {
  let y = 0
  return Object.fromEntries(
    DEVICES.map((device) => {
      const on = selected.includes(device.id)
      const top = y
      if (on) y += LABEL + height(device.id) + GAP
      return [device.id, { on, y: top }]
    }),
  )
}

const build: Build = ({ tl, q, step, final, move, click, type, wait, cursorOut }) => {
  const arrange = (state: number, at?: string) => {
    const next = layout(STATES[state])
    DEVICES.forEach((device, index) => {
      const { on, y } = next[device.id]
      tl.to(
        q(`frame-${device.id}`),
        { y, opacity: on ? 1 : 0, scale: on ? 1 : 0.92, duration: 0.6, ease: 'power3.inOut' },
        index === 0 ? at : '<',
      )
      tl.to(
        q(`chip-${device.id}`),
        {
          backgroundColor: on ? 'rgba(244,114,182,0.18)' : 'rgba(255,255,255,0)',
          borderColor: on ? 'rgba(244,114,182,0.6)' : 'var(--demo-tint-16)',
          duration: 0.2,
        },
        '<',
      )
    })
  }
  const first = layout(STATES[0])
  DEVICES.forEach((device) =>
    tl.set(
      q(`frame-${device.id}`),
      { y: first[device.id].y, opacity: 0, scale: first[device.id].on ? 0.96 : 0.92 },
      0,
    ),
  )

  step(0)
  type('url-text', URLS[0], { at: 0.2, speed: 0.03 })
  arrange(0, '>')

  step(1, '+=0.5')
  move('chip-ipad-mini')
  click('chip-ipad-mini')
  arrange(1, '<')

  step(2, '+=0.6')
  move('chip-iphone')
  click('chip-iphone')
  arrange(2, '<')

  step(3, '+=0.6')
  move('url', { ax: 0.9 })
  click('url')
  type('url-text', URLS[1], { speed: 0.03 })
  tl.to(
    ['ipad-mini', 'laptop'].map((id) => q(`landing-${id}`)),
    { opacity: 0, duration: 0.2 },
  )
  tl.fromTo(
    ['ipad-mini', 'laptop'].map((id) => q(`article-${id}`)),
    { opacity: 0 },
    { opacity: 1, duration: 0.3, stagger: 0.1 },
    '<0.1',
  )
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Responsive Viewer stacking device frames of a page, adding and removing presets, then loading a new URL"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <span
            data-d="url"
            className="flex h-7 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[10px] text-ink"
          >
            <span
              data-d="url-text"
              className="empty:before:text-muted empty:before:content-['Type_a_URL,_e.g._example.com']"
            />
          </span>
          <div className="flex flex-wrap gap-1.5">
            {DEVICES.map((device) => (
              <span
                key={device.id}
                data-d={`chip-${device.id}`}
                className={cn(
                  'rounded-md border px-2 py-1 text-[10px] text-ink-soft',
                  STATES[0].includes(device.id)
                    ? 'border-[#f472b6]/60 bg-[#f472b6]/20'
                    : 'border-line-strong',
                )}
              >
                {device.label}
              </span>
            ))}
          </div>
          <div className="relative min-h-0 flex-1">
            {DEVICES.map((device) => (
              <div
                key={device.id}
                data-d={`frame-${device.id}`}
                className="absolute inset-x-0 top-0 origin-top rounded-lg border border-line p-1.5 opacity-0"
              >
                <p className="text-[9.5px] font-medium text-ink-soft" style={{ height: LABEL - 3 }}>
                  {device.label}
                </p>
                <div
                  className="relative overflow-hidden rounded border border-line bg-white"
                  style={{ height: height(device.id) }}
                >
                  {(['landing', 'article'] as const).map((variant) => (
                    <div
                      key={variant}
                      data-d={`${variant}-${device.id}`}
                      className={cn(
                        'absolute left-0 top-0 h-[400%] w-[200%] origin-top-left scale-50',
                        variant === 'article' && 'opacity-0',
                      )}
                    >
                      <MockPage variant={variant} />
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
